insert into public.products(slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available) select slug,'entrance','Abwehr','Megapolis',name,'Сталь, МДФ-накладки та заводські покриття','Сучасний','Заводські декори','Ціна за запитом',name || ' — ' || lower(construction) || ' серії Megapolis. Три контури ущільнення та посилена конструкція допомагають забезпечити комфорт і захист; точну комплектацію, декори й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика Abwehr','Колекція Megapolis','3 контури ущільнення'),photos[1],99999,false from t on conflict(slug) do update set name=excluded.name,description=excluded.description,features=excluded.features,image_path=excluded.image_path;
insert into public.product_specs(product_slug,label,value,sort_order,is_active) select slug,label,value,sort_order,true from t cross join lateral(values('Тип конструкції',construction,10),('Колекція','Megapolis',20),('Призначення',case when construction like '%тамбура%' then 'Для холодного тамбура' else 'Для квартири' end,30),('Контури ущільнення','3 контури',40))s(label,value,sort_order) on conflict(product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;
insert into public.product_sources(product_slug,source_name,source_url,source_product_name,verification_status,verified_at,notes) select slug,'ABWEHR',url,name || ' · Megapolis · код ' || code,'verified',now(),'Офіційна картка виробника: окрема модель Megapolis та фотогалерея.' from t where not exists(select 1 from public.product_sources x where x.product_slug=t.slug and x.source_url=t.url);
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select slug,'main','Головне фото',photos[1],0 from t where not exists(select 1 from public.product_media x where x.product_slug=t.slug and x.kind='main' and x.image_path=t.photos[1]);
insert into public.product_media(product_slug,kind,label,image_path,sort_order) select t.slug,'gallery','Офіційне фото '||p.ordinality,p.path,p.ordinality from t cross join lateral unnest(t.photos) with ordinality p(path,ordinality) where not exists(select 1 from public.product_media x where x.product_slug=t.slug and x.kind='gallery' and x.image_path=p.path);
